    char *p = malloc(10);
    if (p == NULL) {                /* ★ malloc 也会失败，也要检查 */
        perror("malloc");
        return 1;
    }
    strcpy(p, "hello");

    if (which == 1) {
        /* 越界写：p 只有 10 字节，往第 10 个位置写 */
        p[10] = '!';
        write(1, p, 11);              /* 这里可能打印出 "hello!"，也可能崩溃 */

    } else if (which == 2) {
        /* use-after-free：先 free，再用 */
        free(p);
        write(1, p, 5);               /* 这里可能打印出 "hello"，也可能崩溃 */

    } else if (which == 3) {
        /* double free：free 两次 */
        free(p);
        free(p);                      /* 这里可能崩溃，也可能没事 */
        write(1, p, 5);               /* 这里可能打印出 "hello"，也可能崩溃 */

    } else if (which == 4) {
        /* 泄漏：循环 malloc 100 次，一次都不 free */
        malloc(100);
        write(1, p, 5);               /* 这里可能打印出 "hello"，也可能崩溃 */
    }

    return 0;
}

