# 任务：`15_server.c` —— echo 服务器

功能：**监听 8080，接受一个连接，把收到的东西原样发回去。**

```c
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <netinet/in.h>

int main(void)
{
    char buf[256];

    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd < 0) { perror("socket"); return 1; }

    int opt = 1;
    setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));          /* ★ 先清零，否则有垃圾字段 */
    addr.sin_family      = AF_INET;
    addr.sin_port        = htons(8080);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(listen_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); return 1;
    }

    if (listen(listen_fd, 5) < 0) { perror("listen"); return 1; }

    printf("监听 8080，等待连接...\n");

    int conn_fd = accept(listen_fd, NULL, NULL);
    if (conn_fd < 0) { perror("accept"); return 1; }

    printf("有人连进来了，conn_fd = %d, listen_fd = %d\n", conn_fd, listen_fd);

    /* ===== 这里你自己写 =====
       循环 read(conn_fd, ...)，读到什么就 write 回去
       read 返回 0 表示对方关闭了连接 → 跳出循环
       —— 就是你 02_cat.c 里那个循环，换个 fd 而已
    */

    close(conn_fd);
    close(listen_fd);
    return 0;
}
```

**最后那段循环你自己写** —— 结构跟 `02_cat.c` 完全一样，只是读写的 fd 换成了 `conn_fd`。

