#!/usr/bin/env python3
"""最小 PDF 文本提取：inflate 内容流，取 Tj/TJ 里的字符串。

够用来查 TRM 里的寄存器表，不追求排版还原。
"""
import re, sys, zlib

def streams(data):
    for m in re.finditer(rb'stream\r?\n', data):
        start = m.end()
        end = data.find(b'endstream', start)
        if end < 0:
            continue
        raw = data[start:end].rstrip(b'\r\n')
        try:
            yield zlib.decompress(raw)
        except Exception:
            continue

def text_of(content):
    out = []
    # (字符串) Tj    和   [ (a) -250 (b) ] TJ
    for m in re.finditer(rb'\((?:\\.|[^\\()])*\)', content):
        s = m.group()[1:-1]
        s = re.sub(rb'\\([()\\])', rb'\1', s)
        out.append(s.decode('latin-1'))
    return ''.join(out)

def main():
    data = open(sys.argv[1], 'rb').read()
    pat = sys.argv[2].lower() if len(sys.argv) > 2 else None
    for i, c in enumerate(streams(data)):
        t = text_of(c)
        if not t.strip():
            continue
        if pat is None or pat in t.lower():
            print("---- stream %d ----" % i)
            print(t[:4000])

main()
