/****************************************************************************
 * Name: rk3576_i2cbus_uninitialize
 ****************************************************************************/

int rk3576_i2cbus_uninitialize(struct i2c_master_s *dev)
{
  struct rk3576_i2c_priv_s *priv = (struct rk3576_i2c_priv_s *)dev;

  if (priv == NULL)
    {
      return -EINVAL;
    }

  i2c_putreg(priv, RK3576_I2C_CON, 0);
  priv->initialized = false;
  return OK;
}

