  lv_obj_align(g_label_pos, LV_ALIGN_CENTER, 0, 0);

  g_dot = lv_obj_create(scr);
  lv_obj_set_size(g_dot, 30, 30);
  lv_obj_set_style_radius(g_dot, LV_RADIUS_CIRCLE, 0);
  lv_obj_set_style_bg_color(g_dot, lv_color_hex(0xff5252), 0);
