  uint32_t          src_hz;           /* 控制器源时钟          */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct rk3576_dwmmc_dev_s g_dwmmc;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: dw_update_clk
 *
 * Description:
 *   把 CLKDIV/CLKENA 的改动送进卡时钟域。
 *
 *   ★ dw_mmc 与 SDHCI 在这里有本质区别：CLKDIV 和 CLKENA 写完**不会
 *     立即生效**，必须发一条带 UPD_CLK 位的空命令，由控制器在内部同步。
 *     漏掉这一步的表现是时钟始终停在上一个值，而寄存器读回却是新值 ——
 *     读回一致会让人误以为已经生效。
 *
 ****************************************************************************/

static int dw_update_clk(void)
{
  int us;

  dw_putreg(DWMMC_CMD, DWMMC_CMD_START | DWMMC_CMD_UPD_CLK |
                       DWMMC_CMD_PRV_DAT_WAIT);

  for (us = 0; us < 100000; us++)
    {
      if ((dw_getreg(DWMMC_CMD) & DWMMC_CMD_START) == 0)
        {
          return OK;
        }

      up_udelay(1);
    }

  syslog(LOG_ERR, "ERROR: DWMMC 时钟更新超时 CMD=0x%08" PRIx32 "\n",
         dw_getreg(DWMMC_CMD));
  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: dw_set_clock_hz
 ****************************************************************************/

static void dw_set_clock_hz(struct rk3576_dwmmc_dev_s *priv, uint32_t hz)
{
  uint32_t div;

  /* 先停时钟再改分频 —— 运行中改分频会产生毛刺。 */

  dw_putreg(DWMMC_CLKENA, 0);
  dw_update_clk();

  if (hz == 0)
    {
      return;
    }

  /* dw_mmc 的 CLKDIV 是**二倍分频**：实际 = src / (2 * div)，div=0 表示
   * 直通（分频比 1）。按 SDHCI 的 div 语义写会得到一半的时钟。
   */

  if (hz >= priv->src_hz)
    {
      div = 0;
    }
  else
    {
      div = (priv->src_hz + (hz * 2) - 1) / (hz * 2);
      if (div > 0xff)
        {
          div = 0xff;
        }
    }

  dw_putreg(DWMMC_CLKDIV, div);
  dw_update_clk();

  dw_putreg(DWMMC_CLKENA, DWMMC_CLKENA_ENABLE);
  dw_update_clk();

  syslog(LOG_INFO,
         "DWMMC: 卡时钟 目标 %" PRIu32 "Hz div=%" PRIu32
         " 实际 %" PRIu32 "Hz\n",
         hz, div, div == 0 ? priv->src_hz : priv->src_hz / (2 * div));
}

/****************************************************************************
 * Name: dw_fifo_reset
 ****************************************************************************/

static void dw_fifo_reset(void)
{
  uint32_t val = dw_getreg(DWMMC_CTRL);
  int us;

  dw_putreg(DWMMC_CTRL, val | DWMMC_CTRL_FIFO_RESET);

  for (us = 0; us < 100000; us++)
    {
      if ((dw_getreg(DWMMC_CTRL) & DWMMC_CTRL_FIFO_RESET) == 0)
        {
          return;
        }

      up_udelay(1);
    }

  syslog(LOG_WARNING, "DWMMC: FIFO 复位未自清\n");
}

/****************************************************************************
 * SDIO 接口实现
 ****************************************************************************/

static void rk3576_dwmmc_reset(struct sdio_dev_s *dev)
{
  struct rk3576_dwmmc_dev_s *priv = (struct rk3576_dwmmc_dev_s *)dev;

  dw_reset_ctrl();
  dw_putreg(DWMMC_RINTSTS, DWMMC_INT_ALL);
  dw_putreg(DWMMC_INTMASK, 0);
  dw_putreg(DWMMC_TMOUT, 0xffffffff);
  dw_putreg(DWMMC_CTYPE, DWMMC_CTYPE_1BIT);

  priv->buffer     = NULL;
  priv->remaining  = 0;
  priv->widebus    = false;
  priv->waitevents = 0;
}

static sdio_capset_t rk3576_dwmmc_capabilities(struct sdio_dev_s *dev)
{
  UNUSED(dev);

  /* ★ 必须报 4BIT_ONLY。
   *
   *   NuttX 的 mmcsd 层在这里不对称：CMD6 切卡的总线宽度要求
   *   priv->buswidth 带 4BIT 标志，而该标志只在 caps 含
   *   SDIO_CAPS_4BIT_ONLY 时才置位；但 SDIO_WIDEBUS(true) 只看
   *   IS_MMC()。报 0 的话会出现"主机 4 位、卡 1 位"的错配 ——
   *   这个坑在 eMMC 那边踩过一次。
   */

  return SDIO_CAPS_4BIT_ONLY;
}

static sdio_statset_t rk3576_dwmmc_status(struct sdio_dev_s *dev)
{
  UNUSED(dev);

  /* 用硬件的卡检测脚，而不是恒返回 PRESENT。SD 卡是可插拔的，
   * 这里说实话才有意义。
   */

  return DWMMC_CDETECT_PRESENT(dw_getreg(DWMMC_CDETECT)) ?
         SDIO_STATUS_PRESENT : 0;
}

static void rk3576_dwmmc_widebus(struct sdio_dev_s *dev, bool wide)
{
  struct rk3576_dwmmc_dev_s *priv = (struct rk3576_dwmmc_dev_s *)dev;

  priv->widebus = wide;
  dw_putreg(DWMMC_CTYPE, wide ? DWMMC_CTYPE_4BIT : DWMMC_CTYPE_1BIT);
}

static void rk3576_dwmmc_clock(struct sdio_dev_s *dev, enum sdio_clock_e rate)
{
  struct rk3576_dwmmc_dev_s *priv = (struct rk3576_dwmmc_dev_s *)dev;

  switch (rate)
    {
      case CLOCK_SDIO_DISABLED:
        dw_set_clock_hz(priv, 0);
        break;

      case CLOCK_IDMODE:
        dw_set_clock_hz(priv, 400000);
        break;

      case CLOCK_MMC_TRANSFER:
      case CLOCK_SD_TRANSFER_1BIT:
      case CLOCK_SD_TRANSFER_4BIT:
      default:
        dw_set_clock_hz(priv, 25000000);
        break;
    }
}

static int rk3576_dwmmc_attach(struct sdio_dev_s *dev)
{
  UNUSED(dev);

  /* 轮询式实现，不接中断。中断版本待后续补。 */

  dw_putreg(DWMMC_INTMASK, 0);
  return OK;
}

static int rk3576_dwmmc_sendcmd(struct sdio_dev_s *dev, uint32_t cmd,
                                uint32_t arg)
{
  struct rk3576_dwmmc_dev_s *priv = (struct rk3576_dwmmc_dev_s *)dev;
  uint32_t regval = DWMMC_CMD_START | DWMMC_CMD_USE_HOLD_REG;
  uint32_t datalen;
  int us;

  regval |= DWMMC_CMD_INDX(cmd & MMCSD_CMDIDX_MASK);

  switch (cmd & MMCSD_RESPONSE_MASK)
    {
      case MMCSD_NO_RESPONSE:
        break;

      case MMCSD_R2_RESPONSE:
        regval |= DWMMC_CMD_RESP_EXP | DWMMC_CMD_RESP_LONG |
                  DWMMC_CMD_RESP_CRC;
        break;

      case MMCSD_R3_RESPONSE:
      case MMCSD_R4_RESPONSE:
        regval |= DWMMC_CMD_RESP_EXP;    /* 这两种响应没有 CRC */
        break;

      default:
        regval |= DWMMC_CMD_RESP_EXP | DWMMC_CMD_RESP_CRC;
        break;
    }

  if (priv->buffer != NULL && priv->remaining > 0)
    {
      regval |= DWMMC_CMD_DAT_EXP | DWMMC_CMD_PRV_DAT_WAIT;
      if (priv->is_write)
        {
          regval |= DWMMC_CMD_DAT_WR;
        }

      datalen = priv->remaining;
      dw_putreg(DWMMC_BLKSIZ, priv->blocksize);
      dw_putreg(DWMMC_BYTCNT, datalen);
    }

  /* CMD0 需要带初始化序列（80 个时钟） */

  if ((cmd & MMCSD_CMDIDX_MASK) == 0)
    {
      regval |= DWMMC_CMD_INIT;
    }

  dw_putreg(DWMMC_RINTSTS, DWMMC_INT_ALL);
  dw_putreg(DWMMC_CMDARG, arg);
  dw_putreg(DWMMC_CMD, regval);

  /* 等待命令被控制器接受（START 位自清）。这一步不等于命令完成，
   * 只是控制器收下了 —— 两者分开，超时时能说清卡在哪一步。
   */

  for (us = 0; us < 100000; us++)
    {
      if ((dw_getreg(DWMMC_CMD) & DWMMC_CMD_START) == 0)
        {
          return OK;
        }

      up_udelay(1);
    }

  syslog(LOG_ERR,
         "ERROR: DWMMC CMD%" PRIu32 " 未被接受 CMD=0x%08" PRIx32
         " STATUS=0x%08" PRIx32 "\n",
         cmd & MMCSD_CMDIDX_MASK, dw_getreg(DWMMC_CMD),
         dw_getreg(DWMMC_STATUS));
  return -ETIMEDOUT;
}

static int rk3576_dwmmc_waitresponse(struct sdio_dev_s *dev, uint32_t cmd)
{
  UNUSED(dev);
  uint32_t sts;
  int us;

  for (us = 0; us < 500000; us++)
    {
      sts = dw_getreg(DWMMC_RINTSTS);

      if (sts & DWMMC_INT_CMD_ERROR)
        {
          /* RTO（响应超时）在探测流程里是正常现象：mmcsd 会先试
           * SD 的命令再试 MMC 的，不认得的那条必然超时。所以这里
           * 只在非 RTO 的错误上打日志，避免刷屏掩盖真正的问题。
           */

          if ((sts & DWMMC_INT_RTO) == 0)
            {
              syslog(LOG_ERR,
                     "ERROR: DWMMC CMD%" PRIu32 " 响应错误 RINTSTS=0x%08"
                     PRIx32 "\n", cmd & MMCSD_CMDIDX_MASK, sts);
            }

          dw_putreg(DWMMC_RINTSTS, DWMMC_INT_CMD_ERROR);
          return (sts & DWMMC_INT_RTO) ? -ETIMEDOUT : -EIO;
        }

      if (sts & DWMMC_INT_CMD_DONE)
        {
          dw_putreg(DWMMC_RINTSTS, DWMMC_INT_CMD_DONE);
          return OK;
        }

      up_udelay(1);
    }

  syslog(LOG_ERR,
         "ERROR: DWMMC CMD%" PRIu32 " 无响应 RINTSTS=0x%08" PRIx32
         " STATUS=0x%08" PRIx32 "\n",
         cmd & MMCSD_CMDIDX_MASK, dw_getreg(DWMMC_RINTSTS),
         dw_getreg(DWMMC_STATUS));
  return -ETIMEDOUT;
}

static int rk3576_dwmmc_recvshort(struct sdio_dev_s *dev, uint32_t cmd,
                                  uint32_t *rshort)
{
  UNUSED(dev);
  UNUSED(cmd);

  if (rshort != NULL)
    {
      *rshort = dw_getreg(DWMMC_RESP0);
    }

  return OK;
}

static int rk3576_dwmmc_recvlong(struct sdio_dev_s *dev, uint32_t cmd,
                                 uint32_t rlong[4])
{
  UNUSED(dev);
  UNUSED(cmd);

  if (rlong == NULL)
    {
      return -EINVAL;
    }

  /* ★ dw_mmc 的 R2 与 SDHCI 不同，这里不需要移位。
   *
   *   SDHCI 把 R[127:8] 放在寄存器里，取值时要整体左移 8 位；
   *   dw_mmc 的 RESP0..3 已经是对齐的，RESP3 是最高 32 位。
   *   照搬 SDHCI 的移位会让 CID/CSD 整体错一个字节，表现为
   *   厂商号读成 0、容量算错 —— eMMC 那边正是这么发现的。
   */

  rlong[0] = dw_getreg(DWMMC_RESP3);
  rlong[1] = dw_getreg(DWMMC_RESP2);
  rlong[2] = dw_getreg(DWMMC_RESP1);
  rlong[3] = dw_getreg(DWMMC_RESP0);
  return OK;
}

#ifdef CONFIG_SDIO_BLOCKSETUP
static void rk3576_dwmmc_blocksetup(struct sdio_dev_s *dev,
                                    unsigned int blocklen,
                                    unsigned int nblocks)
{
  struct rk3576_dwmmc_dev_s *priv = (struct rk3576_dwmmc_dev_s *)dev;

