/****************************************************************************
 * Name: rk3576_dwmmc_initialize
 *
 * Description:
 *   返回可交给 mmcsd_slotinitialize() 的 sdio_dev_s。
 *   必须在 rk3576_dwmmc_probe() 成功之后调用。
 *
 ****************************************************************************/

struct sdio_dev_s *rk3576_dwmmc_initialize(void)
{
  struct rk3576_dwmmc_dev_s *priv = &g_dwmmc;
  uint32_t hcon;
  uint32_t depth;

  priv->dev = g_dwmmc_ops;

  /* FIFO 数据窗口的偏移由数据总线宽度决定：32 位在 0x100，64 位在 0x200。
   * 取错的话读写落到别的寄存器上，不报错但数据全乱。
   */

  hcon = dw_getreg(DWMMC_HCON);
  priv->fifo_off = (DWMMC_GET_HDATA_WIDTH(hcon) >= 2) ?
                   DWMMC_DATA_64BIT : DWMMC_DATA_32BIT;

  /* 源时钟：上面把选源设成了 xin24m、不分频。 */

  priv->src_hz = 24000000;

  /* FIFO 水位：msize=0（1 字突发），收水位取深度一半，发水位同。
   * 深度按 dtb 的 256（FIFOTH 复位值反推得到的是 depth/2-1，
   * 见 probe 里打印的那两个数）。
   */

  depth = 256;
  dw_putreg(DWMMC_FIFOTH,
            DWMMC_SET_FIFOTH(0, depth / 2 - 1, depth / 2));

  dw_putreg(DWMMC_CTRL, DWMMC_CTRL_INT_ENABLE);

  syslog(LOG_INFO,
         "DWMMC: sdio_dev 就绪 FIFO 窗口=0x%03" PRIx32
         " 源时钟=%" PRIu32 "Hz\n", priv->fifo_off, priv->src_hz);

  return &priv->dev;
}
