 *     不清的话第二次判断必然错。清除用 GLBRST_ST 写 1 清。
 *
 ****************************************************************************/

int board_reset_cause(FAR struct boardioc_reset_cause_s *cause)
{
  uint32_t st;

  if (cause == NULL)
    {
      return -EINVAL;
    }

  st = getreg32(RK3576_CRU_ADDR + 0x0c04);

  if (st & ((1u << 6) | (1u << 5) | (0x1fu << 11)))
