static void print_usage(const char *prog)
{
  printf("Usage: %s [-d?]\n", prog);
  puts("  -d --device device to use (default /dev/spi0)\n"
       "  -i --read file to transfer\n"
       "  -o --receive data to output file\n"
       "  -b --bits per word\n"
