  struct spi_trans_s trans =
  {
    .txbuffer = tx_buf,
    .rxbuffer = rx_buf,
    .nwords = size,
  };

  struct spi_sequence_s seq =
  {
    .mode = 0,
    .nbits = spi->bits,
    .frequency = spi->speed,
    .ntrans = 1,
    .trans = &trans,
  };

  ret = ioctl(spi->fd, SPIIOC_TRANSFER, &seq);
  assert_false(ret < 0);

  if (spi->output_file)
    {
      out_fd = open(spi->output_file, O_WRONLY | O_CREAT | O_TRUNC, 0666);
      assert_false(out_fd < 0);

      ret = write(out_fd, rx_buf, size);
      close(out_fd);
    }

