int rk3576_pinmux_setpull(int bank, int pin, unsigned int pull)
{
  uint32_t off;
  int shift;
  int ret;

  if (pull > 3)
    {
      return -EINVAL;
    }

  ret = pull_reg(bank, pin, &off, &shift);
  if (ret < 0)
    {
      return ret;
    }

  /* 高 16 位写使能掩码，单次写即原子。 */

  putreg32((0x3u << (shift + 16)) | ((pull & 0x3) << shift),
           RK3576_IOC_GRF_ADDR + off);
  return OK;
}

