static uint32_t rk3576_i2c_wait(struct rk3576_i2c_priv_s *priv,
                                uint32_t mask)
{
  uint32_t ipd;
  int us;

  for (us = 0; us < I2C_POLL_TIMEOUT_US; us++)
    {
      ipd = i2c_getreg(priv, RK3576_I2C_IPD);
      if ((ipd & mask) != 0)
        {
          i2c_putreg(priv, RK3576_I2C_IPD, ipd & mask);   /* 写 1 清 */
          g_last_hit = ipd;             /* 留给 diag 用 */
          return ipd & mask;
        }

      up_udelay(1);
    }

  return 0;
}

