      g_cam_buf[0] = kmm_memalign(CAM_BUF_ALIGN, CAM_FRAME_BYTES);
      g_cam_buf[1] = kmm_memalign(CAM_BUF_ALIGN, CAM_FRAME_BYTES);

      if (g_cam_buf[0] == NULL || g_cam_buf[1] == NULL)
        {
          syslog(LOG_ERR, "摄像头: 取图缓冲分配失败（每个 %d 字节）\\n",
                 CAM_FRAME_BYTES);
